CREATE TABLE model_preparation_recoveries (
    id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
    tenant_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    workspace_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    preparation_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    previous_attempt_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    previous_node_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    next_node_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    next_attempt_number integer NOT NULL CHECK(next_attempt_number BETWEEN 2 AND 1000),
    requested_by CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    requested_audience VARCHAR(8) NOT NULL CHECK(requested_audience IN ('portal','admin')),
    requested_epoch bigint NOT NULL CHECK(requested_epoch>=0),
    membership_authority CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
    reason VARCHAR(500) NOT NULL CHECK(CHAR_LENGTH(TRIM(reason))>0),
    creation_key CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    creation_fingerprint VARBINARY(32) NOT NULL CHECK(OCTET_LENGTH(creation_fingerprint)=32),
    dispatched_attempt_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
    applied_at DATETIME(6),
    created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    UNIQUE(tenant_id,workspace_id,preparation_id,id),
    UNIQUE(preparation_id,requested_by,requested_audience,creation_key),
    FOREIGN KEY(tenant_id,workspace_id,preparation_id) REFERENCES model_preparations(tenant_id,workspace_id,id),
    FOREIGN KEY(tenant_id,workspace_id,preparation_id,previous_attempt_id) REFERENCES model_preparation_attempts(tenant_id,workspace_id,preparation_id,id),
    FOREIGN KEY(tenant_id,workspace_id,previous_node_id) REFERENCES managed_nodes(tenant_id,workspace_id,id),
    FOREIGN KEY(tenant_id,workspace_id,next_node_id) REFERENCES managed_nodes(tenant_id,workspace_id,id),
    FOREIGN KEY(tenant_id,workspace_id,preparation_id,dispatched_attempt_id) REFERENCES model_preparation_attempts(tenant_id,workspace_id,preparation_id,id),
    CHECK(requested_audience='admin' OR membership_authority IS NOT NULL),
    CHECK((dispatched_attempt_id IS NULL)=(applied_at IS NULL)),
    FOREIGN KEY(requested_by) REFERENCES users(id),
    CONSTRAINT model_preparation_recoveries_id_canonical CHECK(REGEXP_LIKE(id,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
    CONSTRAINT model_preparation_recoveries_tenant_id_canonical CHECK(REGEXP_LIKE(tenant_id,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
    CONSTRAINT model_preparation_recoveries_workspace_id_canonical CHECK(REGEXP_LIKE(workspace_id,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
    CONSTRAINT model_preparation_recoveries_preparation_id_canonical CHECK(REGEXP_LIKE(preparation_id,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
    CONSTRAINT model_preparation_recoveries_previous_attempt_id_canonical CHECK(REGEXP_LIKE(previous_attempt_id,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
    CONSTRAINT model_preparation_recoveries_previous_node_id_canonical CHECK(REGEXP_LIKE(previous_node_id,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
    CONSTRAINT model_preparation_recoveries_next_node_id_canonical CHECK(REGEXP_LIKE(next_node_id,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
    CONSTRAINT model_preparation_recoveries_requested_by_canonical CHECK(REGEXP_LIKE(requested_by,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
    CONSTRAINT model_preparation_recoveries_membership_authority_canonical CHECK(membership_authority IS NULL OR REGEXP_LIKE(membership_authority,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
    CONSTRAINT model_preparation_recoveries_creation_key_canonical CHECK(REGEXP_LIKE(creation_key,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
    CONSTRAINT model_preparation_recoveries_dispatched_attempt_id_canonical CHECK(dispatched_attempt_id IS NULL OR REGEXP_LIKE(dispatched_attempt_id,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
